void *addr = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
size_t len = 4096; // Must be page size aligned

// Initial Protection: Read/Write
*(int*)addr = 42;

// Change protection to Read-Only
int status1 = mprotect(addr, len, PROT_READ);

// Attempting to write now (e.g., *(int*)addr = 5) causes SIGSEGV

// Change protection to No Access
int status2 = mprotect(addr, len, PROT_NONE);

// Attempting to read or write causes SIGSEGV

munmap(addr, len);
